findings.remediation_prompt:
Dans Supabase, active la politique Row Level Security (RLS) sur la table 'orders' :

ALTER TABLE orders ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Lecture réservée au propriétaire"
ON orders FOR SELECT USING (auth.uid() = user_id);

CREATE POLICY "Insertion réservée au propriétaire"
ON orders FOR INSERT WITH CHECK (auth.uid() = user_id);

CREATE POLICY "Modification réservée au propriétaire"
ON orders FOR UPDATE USING (auth.uid() = user_id);
